/* From Uiverse.io by vinodjangid07 - Tags: button, neon, copy, hover effect */
.__UIV_SCOPE__ .Btn {
  width: 120px;
  height: 45px;
  background-color: rgb(65, 64, 64);
  border: none;
  box-shadow: 5px 5px 15px rgba(0, 0, 0, 0.342);
  border-radius: 5px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  position: relative;
  overflow: hidden;
  transition-duration: .5s;
}

.__UIV_SCOPE__ .text {
  color: rgb(184, 236, 104);
  font-weight: 800;
  letter-spacing: 1.1px;
  z-index: 2;
}

.__UIV_SCOPE__ .svgIcon {
  z-index: 2;
}

.__UIV_SCOPE__ .svgIcon path {
  fill: rgb(184, 236, 104);
}

.__UIV_SCOPE__ .Btn:hover {
  color: rgb(230, 255, 193);
}

.__UIV_SCOPE__ .effect {
  position: absolute;
  width: 10px;
  height: 10px;
  background-color: rgb(184, 236, 104);
  border-radius: 50%;
  z-index: 1;
  opacity: 0;
  transition-duration: .5s;
}

.__UIV_SCOPE__ .Btn:hover .effect {
  transform: scale(15);
  transform-origin: center;
  opacity: 1;
  transition-duration: .5s;
}

.__UIV_SCOPE__ .Btn:hover {
  box-shadow: 0px 0px 5px rgb(184, 236, 104),
  0px 0px 10px rgb(184, 236, 104),
  0px 0px 30px rgb(184, 236, 104);
  transition-duration: .7s;
}

.__UIV_SCOPE__ .Btn:hover .text {
  color: rgb(65, 64, 64);
}

.__UIV_SCOPE__ .Btn:hover .svgIcon path {
  fill: rgb(65, 64, 64);
}
